head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/json2.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
scwin.vScrenID = "ULDSTF06001.xml";
scwin.pLIST_PROMT_SEQ = "";
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd"); // 오늘날짜
scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/**
 * 요약재무자료(YYYY-2,YYYY-1,YYYY) 세팅
 **/
scwin.fn_init = function() {
    $c.stf.showObj(grd_YearFncTotList, false);
    var parentWin = $c.frame.path("../");
    scwin.pLIST_PROMT_SEQ = parentWin.scwin.pLIST_PROMT_SEQ;
    if (scwin.pLIST_PROMT_SEQ == undefined) {
        scwin.pLIST_PROMT_SEQ = "";
    }
    var YY_3 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 3;
    var YY_2 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 2;
    var YY_1 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 1;
    var YY = scwin.vCurDate.substr(0, 4);
    var YY1 = parseInt(scwin.vCurDate.substring(0, 4), 10) + parseInt(1, 10);
    var YY2 = parseInt(scwin.vCurDate.substring(0, 4), 10) + parseInt(2, 10);
    var YY3 = parseInt(scwin.vCurDate.substring(0, 4), 10) + parseInt(3, 10);
    var strCbd_SME_YN = YY + "^" + YY + "," + YY1 + "^" + YY1 + "," + YY2 + "^" + YY2 + "," + YY3 + "^" + YY3 + ",9999^ 미정"; //	상장예정시기 setting(당해년도,Y+1,Y+2,Y+3,미정)		
    cmb_LIST_SCHDL_TM.CBData = strCbd_SME_YN;
    $c.stf.setObjectValue(txb_YY3, YY_3 + "년"); //	요약재무자료 Title(Y-2)
    $c.stf.setObjectValue(txb_YY2, YY_2 + "년"); //	요약재무자료 Title(Y-1)
    $c.stf.setObjectValue(txb_YY1, YY_1 + "년"); //	요약재무자료 Title(Y)		

};



/**
 *	공통코드
 **/
scwin.fn_searchCode = function() {
    /*
    03270	면담방법코드(1:방문,2:유선,3:서면,4:기타)
    03271	면담적극성구분코드(1:매우적극,2:적극,3:보통,4:소극,5:면담거절) 
    03286	방문사유구분코드(1:청구예정,2:상장유치,3:주관사요청,4:회사요청,5:기타)
    03287  상장의사구분코드 (1:적극,2:중립,3:소극)	
    */
    var arrCid = [{
        cid: "INTVIEW_METHD_CD",
        cnm: "cmb_INTVIEW_METHD_CD"
    }, {
        cid: "INTVIEW_POSIT_TP_CD",
        cnm: "cmb_INTVIEW_POSIT_TP_CD"
    }, {
        cid: "VIST_RSN_TP_CD",
        cnm: "cmb_VIST_RSN_TP_CD"
    }, {
        cid: "LIST_INTNT_TP_CD",
        cnm: "cmb_LIST_INTNT_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM";
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='INTVIEW_METHD_CD','INTVIEW_POSIT_TP_CD','VIST_RSN_TP_CD','LIST_INTNT_TP_CD'";
    dts_Code.DataID = encodeURI(url);
    dts_Code.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Code.getTotalRow(); j++) {
            if (dts_Code.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Code.getCellData(j, "VALUE") + "^" + dts_Code.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }

    // 담당자
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listInvstgEmpList";
    dts_EmpNo.DataID = encodeURI(url);
    dts_EmpNo.Reset();
    strCbd = "";
    if (dts_EmpNo.getTotalRow() > 0) {
        strCbd = "^선택";
        for (var i = 1; i <= dts_EmpNo.getTotalRow(); i++) {
            strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_EmpNo.getCellData(i, "EMP_NO") + "^" + dts_EmpNo.getCellData(i, "DEP_EMP_NM");
        }
        cmb_INTVIEW_CHRG_EMP_NO.CBData = strCbd; //	담당자
        cmb_INTVIEW_CHRG_EMP_NO2.CBData = strCbd; //	담당자2
        cmb_INTVIEW_CHRG_EMP_NO3.CBData = strCbd; //	담당자3				

    }

    //	주관사명
    dts_MajagntInst.DataID = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listLeadCom&For=''";
    dts_MajagntInst.Reset();
    for (var k = 1; k <= dts_MajagntInst.getTotalRow(); k++) {
        if (dts_MajagntInst.getCellData(k, "TEXT") == "") {
            //널값은 삭제
            $c.cp.removeRow(dts_MajagntInst, k);
        }
    }
};




/**
 * 우편번호
 **/
scwin.fn_SetParZipCd = function(arrPar) {
    txb_LOC_ZIPCD.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_LOC_ADDR.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};


/**
 *	조회
 **/
scwin.fn_list_sync = function() {
    //	상장유치면담이력 조회
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listPromtIntviewHistList";
    url += "&inputMessageId=LISTPRMTINTIWHIST_INOUT&outputMessageId=LISTPRMTINTIWHIST_INOUT";
    url += "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ;
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();

    //	면담대상자 조회
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=udgoConsultrList";
    url += "&inputMessageId=UDGOCONSULTRLIST_INOUT&outputMessageId=UDGOCONSULTRLIST_INOUT";
    url += "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ;
    dts_IntviewList.DataID = encodeURI(url);
    dts_IntviewList.Reset();

    //	요약재무자료 조회
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listPromtFncList";
    url += "&inputMessageId=LISTPROMTFNCLIST_INOUT&outputMessageId=LISTPROMTFNCLIST_INOUT";
    url += "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ;
    dts_YearFnc.DataID = encodeURI(url);
    dts_YearFnc.Reset();

    //	요약재무자료 전체조회(엑셀연동)
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listPromtFncTotalList";
    url += "&inputMessageId=LISTPROMTFNCTOTALLIST_INOUT&outputMessageId=LISTPROMTFNCTOTALLIST_INOUT";
    url += "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ;
    dts_YearFncTotal.DataID = encodeURI(url);
    dts_YearFncTotal.Reset();
    if (dts_List.getTotalRow() < 1) {
        dts_List.insertRow();
        $c.stf.showObj(txb_INTVIEW_METHD_MISC_CONTN, false);
        $c.stf.showObj(cmb_LEADCOM_MBR_NO, false);
        $c.stf.showObj(edt_MAJAGNT_COM_CONTRT_TRD_DD, false);
        $c.stf.showObj(img_MAJAGNT_COM_CONTRT_TRD_DD, false);
        $c.stf.showObj(label_42, false);
    }
    scwin.fn_setHeader();
    scwin.fn_intviewSetting(0);
};


/**
 * 면담대상 rowPosition에 따른 editBoxSetting
 **/
scwin.fn_intviewSetting = function(rPos) {
    if (dts_IntviewList.getTotalRow() > 0) {
        $c.stf.setObjectValue(txb_UDGOCONSULTR_NM, dts_IntviewList.getCellData(rPos, "UDGOCONSULTR_NM"));
        $c.stf.setObjectValue(txb_UDGOCONSULTR_DEP_NM, dts_IntviewList.getCellData(rPos, "UDGOCONSULTR_DEP_NM"));
        $c.stf.setObjectValue(txb_UDGOCONSULTR_JOBPOS_NM, dts_IntviewList.getCellData(rPos, "UDGOCONSULTR_JOBPOS_NM"));
        $c.stf.setObjectValue(txb_UDGOCONSULTR_TEL_NO, dts_IntviewList.getCellData(rPos, "UDGOCONSULTR_TEL_NO"));
        $c.stf.setObjectValue(txb_UDGOCONSULTR_CELLPHONE_NO, dts_IntviewList.getCellData(rPos, "UDGOCONSULTR_CELLPHONE_NO"));
        $c.stf.setObjectValue(txb_UDGOCONSULTR_EMAIL, dts_IntviewList.getCellData(rPos, "UDGOCONSULTR_EMAIL"));
    } else {
        $c.stf.setObjectValue(txb_UDGOCONSULTR_NM, "");
        $c.stf.setObjectValue(txb_UDGOCONSULTR_DEP_NM, "");
        $c.stf.setObjectValue(txb_UDGOCONSULTR_JOBPOS_NM, "");
        $c.stf.setObjectValue(txb_UDGOCONSULTR_TEL_NO, "");
        $c.stf.setObjectValue(txb_UDGOCONSULTR_CELLPHONE_NO, "");
        $c.stf.setObjectValue(txb_UDGOCONSULTR_EMAIL, "");
    }
};



/**
 * 입력값 Check
 **/
scwin.fn_checkForm = function() {
    if ($c.stf.getObjectValue(txb_COM_NM) == "") {
        $c.win.alert("[회사명]을  입력하세요.");
        txb_COM_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_PROG_YYS) != "") {
        var chk_date = $c.stf.getObjectValue(edt_PROG_YYS) + "0101";
        if ($c.ut.isDate(chk_date) == false) {
            $c.win.alert("[년도(YYYY)]를 입력하세요.");
            edt_PROG_YYS.focus();
            return false;
        }
    }
    return true;
};


/**
 * 면담대상 DataSet Del 
 **/
scwin.fn_delIntviewList = function() {
    if (dts_IntviewList.getTotalRow() < 1) {
        $c.win.alert("삭제할 [면담대상]이 없습니다.");
        return false;
    } else {
        $c.cp.removeRow(dts_IntviewList, dts_IntviewList.getRowPosition());
        scwin.fn_intviewSetting(dts_IntviewList.getRowPosition());
    }
};



/**
 * 면담대상 Dataset Add
 **/
scwin.fn_addIntviewList = function() {
    if (dts_IntviewList.getTotalRow() > 9) {
        $c.win.alert("[면담대상]은  최대10명 입니다.");
    } else {
        if ($c.stf.getObjectValue(txb_UDGOCONSULTR_NM) == "") {
            $c.win.alert("[이름]을 입력하세요.");
            txb_UDGOCONSULTR_NM.focus();
            return false;
        }
        grd_INTVIEW_PRN.Redraw = false;
        dts_IntviewList.insertRow();
        dts_IntviewList.setCellData(dts_IntviewList.getRowPosition(), "UDGOCONSULTR_NM", $c.stf.getObjectValue(txb_UDGOCONSULTR_NM));
        dts_IntviewList.setCellData(dts_IntviewList.getRowPosition(), "UDGOCONSULTR_DEP_NM", $c.stf.getObjectValue(txb_UDGOCONSULTR_DEP_NM));
        dts_IntviewList.setCellData(dts_IntviewList.getRowPosition(), "UDGOCONSULTR_JOBPOS_NM", $c.stf.getObjectValue(txb_UDGOCONSULTR_JOBPOS_NM));
        dts_IntviewList.setCellData(dts_IntviewList.getRowPosition(), "UDGOCONSULTR_TEL_NO", $c.stf.getObjectValue(txb_UDGOCONSULTR_TEL_NO));
        dts_IntviewList.setCellData(dts_IntviewList.getRowPosition(), "UDGOCONSULTR_CELLPHONE_NO", $c.stf.getObjectValue(txb_UDGOCONSULTR_CELLPHONE_NO));
        dts_IntviewList.setCellData(dts_IntviewList.getRowPosition(), "UDGOCONSULTR_EMAIL", $c.stf.getObjectValue(txb_UDGOCONSULTR_EMAIL));
        grd_INTVIEW_PRN.Redraw = true;
    }
};



/**
 * dts_YearFncChange 의 setHeader
 **/
scwin.fn_setHeader = function() {
    /* 헤더정보:LIST_PROMT_SEQ,	BAS_YY,	ASST_TOTAMT,	EQTYCAP, DEBT_TOTAMT,	SALES,	BZ_PROFT_AMT,	NETINCM_AMT */
    dts_YearFncChange.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=YEARFNCCHG_INOUT";
    dts_YearFncChange.reset();

    /* 헤더정보:LIST_PROMT_SEQ,	SEQ,	UDGOCONSULTR_NM,	UDGOCONSULTR_DEP_NM,	UDGOCONSULTR_JOBPOS_NM,	UDGOCONSULTR_TEL_NO,	 UDGOCONSULTR_CELLPHONE_NO,	UDGOCONSULTR_EMAIL */
    dts_IntviewChange.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=INTVIEWCHG_INOUT";
    dts_IntviewChange.reset();
};


/**
 * dts_IntviewList Dateset -> dts_IntviewChange 변경
 **/
scwin.fn_setIntviewDataSet = function() {
    if (dts_IntviewList.getTotalRow() > 0) {
        for (var i = 1; i <= dts_IntviewList.getTotalRow(); i++) {
            dts_IntviewChange.insertRow();
            dts_IntviewChange.setCellData(dts_IntviewChange.getRowPosition(), "SEQ", i);
            dts_IntviewChange.setCellData(dts_IntviewChange.getRowPosition(), "UDGOCONSULTR_NM", dts_IntviewList.getCellData(i, "UDGOCONSULTR_NM"));
            dts_IntviewChange.setCellData(dts_IntviewChange.getRowPosition(), "UDGOCONSULTR_DEP_NM", dts_IntviewList.getCellData(i, "UDGOCONSULTR_DEP_NM"));
            dts_IntviewChange.setCellData(dts_IntviewChange.getRowPosition(), "UDGOCONSULTR_JOBPOS_NM", dts_IntviewList.getCellData(i, "UDGOCONSULTR_JOBPOS_NM"));
            dts_IntviewChange.setCellData(dts_IntviewChange.getRowPosition(), "UDGOCONSULTR_TEL_NO", dts_IntviewList.getCellData(i, "UDGOCONSULTR_TEL_NO"));
            dts_IntviewChange.setCellData(dts_IntviewChange.getRowPosition(), "UDGOCONSULTR_CELLPHONE_NO", dts_IntviewList.getCellData(i, "UDGOCONSULTR_CELLPHONE_NO"));
            dts_IntviewChange.setCellData(dts_IntviewChange.getRowPosition(), "UDGOCONSULTR_EMAIL", dts_IntviewList.getCellData(i, "UDGOCONSULTR_EMAIL"));
        }
    }
};




/**
 * dts_YearFnc Dateset -> dts_YearFncChange로 변경
 **/
scwin.fn_setYearFncDataSet = function() {
    if (dts_YearFnc.getCellData(1, "ASST_TOTAMT_2") != "" || dts_YearFnc.getCellData(1, "EQTYCAP_2") != "" || dts_YearFnc.getCellData(1, "DEBT_TOTAMT_2") != "" ||
        dts_YearFnc.getCellData(1, "SALES_2") != "" || dts_YearFnc.getCellData(1, "BZ_PROFT_AMT_2") != "" || dts_YearFnc.getCellData(1, "NETINCM_AMT_2") != "") {
        dts_YearFncChange.insertRow();
        dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "BAS_YY", $c.stf.getObjectValue(txb_YY3).substr(0, 4));
        if (dts_YearFnc.getCellData(1, "ASST_TOTAMT_2") != "") {
            dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "ASST_TOTAMT", dts_YearFnc.getCellData(1, "ASST_TOTAMT_2"));
        }
        if (dts_YearFnc.getCellData(1, "EQTYCAP_2") != "") {
            dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "EQTYCAP", dts_YearFnc.getCellData(1, "EQTYCAP_2"));
        }
        if (dts_YearFnc.getCellData(1, "DEBT_TOTAMT_2") != "") {
            dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "DEBT_TOTAMT", dts_YearFnc.getCellData(1, "DEBT_TOTAMT_2"));
        }
        if (dts_YearFnc.getCellData(1, "SALES_2") != "") {
            dts_YearFncChange.setCellData(1, "SALES", dts_YearFnc.getCellData(1, "SALES_2"));
        }
        if (dts_YearFnc.getCellData(1, "BZ_PROFT_AMT_2") != "") {
            dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "BZ_PROFT_AMT", dts_YearFnc.getCellData(1, "BZ_PROFT_AMT_2"));
        }
        if (dts_YearFnc.getCellData(1, "NETINCM_AMT_2") != "") {
            dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "NETINCM_AMT", dts_YearFnc.getCellData(1, "NETINCM_AMT_2"));
        }
    }
    if (dts_YearFnc.getCellData(1, "ASST_TOTAMT_1") != "" || dts_YearFnc.getCellData(1, "EQTYCAP_1") != "" || dts_YearFnc.getCellData(1, "DEBT_TOTAMT_1") != "" ||
        dts_YearFnc.getCellData(1, "SALES_1") != "" || dts_YearFnc.getCellData(1, "BZ_PROFT_AMT_1") != "" || dts_YearFnc.getCellData(1, "NETINCM_AMT_1") != "") {
        dts_YearFncChange.insertRow();
        dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "BAS_YY", $c.stf.getObjectValue(txb_YY2).substr(0, 4));
        if (dts_YearFnc.getCellData(1, "ASST_TOTAMT_1") != "") {
            dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "ASST_TOTAMT", dts_YearFnc.getCellData(1, "ASST_TOTAMT_1"));
        }
        if (dts_YearFnc.getCellData(1, "EQTYCAP_1") != "") {
            dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "EQTYCAP", dts_YearFnc.getCellData(1, "EQTYCAP_1"));
        }
        if (dts_YearFnc.getCellData(1, "DEBT_TOTAMT_1") != "") {
            dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "DEBT_TOTAMT", dts_YearFnc.getCellData(1, "DEBT_TOTAMT_1"));
        }
        if (dts_YearFnc.getCellData(1, "SALES_1") != "") {
            dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "SALES", dts_YearFnc.getCellData(1, "SALES_1"));
        }
        if (dts_YearFnc.getCellData(1, "BZ_PROFT_AMT_1") != "") {
            dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "BZ_PROFT_AMT", dts_YearFnc.getCellData(1, "BZ_PROFT_AMT_1"));
        }
        if (dts_YearFnc.getCellData(1, "NETINCM_AMT_1") != "") {
            dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "NETINCM_AMT", dts_YearFnc.getCellData(1, "NETINCM_AMT_1"));
        }
    }
    if (dts_YearFnc.getCellData(1, "ASST_TOTAMT_0") != "" || dts_YearFnc.getCellData(1, "EQTYCAP_0") != "" || dts_YearFnc.getCellData(1, "DEBT_TOTAMT_0") != "" ||
        dts_YearFnc.getCellData(1, "SALES_0") != "" || dts_YearFnc.getCellData(1, "BZ_PROFT_AMT_0") != "" || dts_YearFnc.getCellData(1, "NETINCM_AMT_0") != "") {
        dts_YearFncChange.insertRow();
        dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "BAS_YY", $c.stf.getObjectValue(txb_YY1).substr(0, 4));
        if (dts_YearFnc.getCellData(1, "ASST_TOTAMT_0") != "") {
            dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "ASST_TOTAMT", dts_YearFnc.getCellData(1, "ASST_TOTAMT_0"));
        }
        if (dts_YearFnc.getCellData(1, "EQTYCAP_0") != "") {
