/**
 * 저장
 **/
scwin.fn_save = function() {
    if (scwin.fn_checkForm()) {
        var trsIdx = "";
        var isEmptyPrn = "Y";
        if (scwin.pLIST_PROMT_SEQ == "") {
            trsIdx = TR_JOB_INSERT;
        } else {
            trsIdx = TR_JOB_UPDATE;
        }
        scwin.fn_setYearFncDataSet();
        scwin.fn_setIntviewDataSet();
        if (dts_IntviewChange.getTotalRow() > 0) {
            isEmptyPrn = "N";
        }
        trs_Save.Action = $c.lc.fn_encodeNSession("/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveListPromtPrfmList");
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_List, I:pInputITW=dts_IntviewChange, I:pInputYF=dts_YearFncChange)";
        trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",IS_EMPTY_PRN=" + isEmptyPrn + ",LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ;
        trs_Save.Post();
    }
};



