/********************************************** 
 * 함수명   : fn_calEqtycap()
 * 설명       : 요약재무자료 최근연도의 자기자본금을 상장요건충족여부 자기자본에 반영
 ***********************************************/
scwin.fn_calEqtycap = function() {
    if ($c.stf.getObjectValue(edt_EQTYCAP_0) != "" && $c.stf.getObjectValue(edt_EQTYCAP_0) != 'undefined') {
        $c.stf.setObjectValue(edt_EQTYCAP, $c.stf.getObjectValue(edt_EQTYCAP_0));
    }
};



/********************************************** 
 * 함수명   : fn_calSales()
 * 설명       : 요약재무자료 최근연도의 매출액을 상장요건충족여부 매출액 최근연도 에 반영
 ***********************************************/
scwin.fn_calSales = function() {
    if ($c.stf.getObjectValue(edt_SALES_0) != "" && $c.stf.getObjectValue(edt_SALES_0) != 'undefined') {
        $c.stf.setObjectValue(edt_RECENT_YY1_SALES, $c.stf.getObjectValue(edt_SALES_0));
    }
};


/********************************************** 
 * 함수명   : fn_calNetincm()
 * 설명       : 요약재무자료 최근연도의 당기순이익을 상장요건충족여부 이익액 최근연도 에 반영
 ***********************************************/
scwin.fn_calNetincm = function() {
    if ($c.stf.getObjectValue(edt_NETINCM_AMT_0) != "" && $c.stf.getObjectValue(edt_NETINCM_AMT_0) != 'undefined') {
        $c.stf.setObjectValue(edt_RECENT_YY1_PROFT_AMT, $c.stf.getObjectValue(edt_NETINCM_AMT_0));
    }
};



/********************************************** 
 * 함수명   : fn_TotNetincm()
 * 설명       : 요약재무자료 당기순이익(3년 합)을  상장요건충족여부 이익액 3년합계에 반영
 ***********************************************/
scwin.fn_TotNetincm = function() {
    var vNetincm_2 = 0;
    var vNetincm_1 = 0;
    var vNetincm_0 = 0;
    var vTot = 0;
    if (isNaN(parseInt($c.stf.getObjectValue(edt_NETINCM_AMT_2)))) {
        vNetincm_2 = 0;
    } else {
        vNetincm_2 = parseInt($c.stf.getObjectValue(edt_NETINCM_AMT_2));
    }
    if (isNaN(parseInt($c.stf.getObjectValue(edt_NETINCM_AMT_1)))) {
        vNetincm_1 = 0;
    } else {
        vNetincm_1 = parseInt($c.stf.getObjectValue(edt_NETINCM_AMT_1));
    }
    if (isNaN(parseInt($c.stf.getObjectValue(edt_NETINCM_AMT_0)))) {
        vNetincm_0 = 0;
    } else {
        vNetincm_0 = parseInt($c.stf.getObjectValue(edt_NETINCM_AMT_0));
    }
    vTot = eval(parseInt(vNetincm_2) + parseInt(vNetincm_1) + parseInt(vNetincm_0));
    if (!(isNaN(vTot))) {
        $c.stf.setObjectValue(edt_RECENT_YY3_PROFT_AMT, vTot);
    }
};



/********************************************** 
 * 함수명   : fn_avgSales()
 * 설명       : 요약재무자료 매출액(3년/3)을  상장요건충족여부 매출액3년 평균최근연도에 반영
 ***********************************************/
scwin.fn_avgSales = function() {
    var vSale_2 = 0;
    var vSale_1 = 0;
    var vSale_0 = 0;
    var vAge = 0;
    if (isNaN(parseInt($c.stf.getObjectValue(edt_SALES_2)))) {
        vSale_2 = 0;
    } else {
        vSale_2 = parseInt($c.stf.getObjectValue(edt_SALES_2));
    }
    if (isNaN(parseInt($c.stf.getObjectValue(edt_SALES_1)))) {
        vSale_1 = 0;
    } else {
        vSale_1 = parseInt($c.stf.getObjectValue(edt_SALES_1));
    }
    if (isNaN(parseInt($c.stf.getObjectValue(edt_SALES_0)))) {
        vSale_0 = 0;
    } else {
        vSale_0 = parseInt($c.stf.getObjectValue(edt_SALES_0));
    }
    vAge = eval(Math.round((parseInt(vSale_2) + parseInt(vSale_1) + parseInt(vSale_0)) / 3));
    if (!(isNaN(vAge))) {
        $c.stf.setObjectValue(edt_RECENT_YY3_AVG_SALES, vAge);
    }
};



