        // 주관계약 체결여부가 예 일때
        $c.stf.showObj(cmb_LEADCOM_MBR_NO, true);
        $c.stf.showObj(edt_MAJAGNT_COM_CONTRT_TRD_DD, true);
        $c.stf.showObj(img_MAJAGNT_COM_CONTRT_TRD_DD, true);
        $c.stf.showObj(label_42, true);
    } else {
        $c.stf.showObj(cmb_LEADCOM_MBR_NO, false);
        $c.stf.showObj(edt_MAJAGNT_COM_CONTRT_TRD_DD, false);
        $c.stf.showObj(img_MAJAGNT_COM_CONTRT_TRD_DD, false);
        $c.stf.showObj(label_42, false);
    }
};
